# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [parse_span("09:00-12:00"), parse_span("13:00-17:00")]
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-17:00")),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_gaps_at_both_ends_and_overlaps_merge(self):
        worked = [parse_span("10:00-12:00"), parse_span("11:00-13:00")]
        self.assertEqual(
            find_gaps(worked, parse_span("09:00-14:00")),
            ["gap 09:00-10:00 (60 min)", "gap 13:00-14:00 (60 min)"],
        )

    def test_nobody_working_is_one_gap(self):
        self.assertEqual(
            find_gaps([], parse_span("09:00-10:30")),
            ["gap 09:00-10:30 (90 min)"],
        )

    def test_full_coverage_has_no_gaps(self):
        worked = [parse_span("09:00-12:00"), parse_span("12:00-17:00")]
        self.assertEqual(find_gaps(worked, parse_span("09:00-17:00")), [])

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([parse_span("08:00-10:00")], parse_span("09:00-17:00"))
        with self.assertRaises(ValueError):
            find_gaps([parse_span("16:00-18:00")], parse_span("09:00-17:00"))


if __name__ == "__main__":
    unittest.main()
